import json
import logging
import six
import socket

from .exception import RpcException, BTSSMJSONRequestError
from ute_common_util.decorators.retry import retry_until_no_exception_or_timeout


class RpcExecutor(object):
    RECEIVE_BUFFER = 16
    LOCAL_HOST = '127.0.0.1'
    _timeout = 10

    def __init__(self, port, timeout=10):
        self._port = port
        self.__class__._timeout = self.__class__._timeout if not timeout else timeout
        self._log = logging.getLogger(__name__)

    def __enter__(self):
        self._socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._socket.close()

    def execute_request(self, request, check_for_errors=True):
        """
        Sends a JSON request through the created socket

        :param string       request:             JSON request
        :param boolean      check_for_errors:   if set to False, then this will not raise exception if there is an error

        :return: JSON output string received
        :rtype: string

        :raises: RpcException - if JSON request failed
        :raises: BTSSMJSONRequestError - if JSON output contains an error value
        """
        self._log.debug('Executing JSON: {}'.format(request))
        json_response = self._retrieve_json_response(request)
        self._log.debug('Received JSON response: {}'.format(json_response))
        if check_for_errors:
            self._check_for_errors(json_response)
        return json_response

    @retry_until_no_exception_or_timeout(timeout=_timeout, on_timeout=RpcException(None, 'Connection timed out'))
    def _connect(self):
        try:
            self._log.debug('Connecting to {}:{}'.format(RpcExecutor.LOCAL_HOST, self._port))
            self._socket.connect_ex((RpcExecutor.LOCAL_HOST, self._port))
            self._log.debug('Connected to {}:{}'.format(RpcExecutor.LOCAL_HOST, self._port))
        except RpcException:
            raise RpcException(None, 'Connection timed out')

    def _retrieve_json_response(self, json_request):
        try:
            json_response = self._send(json_request)
        except Exception as e:
            raise RpcException(e, 'Failed JSON request: \n{}\n'.format(json_request))
        return json_response

    def _send(self, json_request):
        send_param = json_request.encode(encoding='utf_8', errors='strict')
        self._log.info(send_param)
        self._socket.sendall(send_param)
        return self._read_socket_response()

    def _read_socket_response(self):
        result = []
        while True:
            data = self._socket.recv(RpcExecutor.RECEIVE_BUFFER)
            data = data if six.PY2 else data.decode()
            result.append(data)
            if data.find('\n') != -1:
                break
        return ''.join(result)

    def _check_for_errors(self, json_response):
        """
        This method is just a hot fix until CLI fixes their JSON response.
        Proper JSON response in case of error should have the 'error' object. However,
        that is not the case for other operations.
        """
        json_object = json.loads(json_response)
        if 'error' in json_object:
            raise BTSSMJSONRequestError('Error Code: {} \nError Message: {}'.format(json_object['error']['code'], json_object['error']['message']))
